from scipy import ndimage
def f(I):
    I=np.array(I); out=I.copy(); H,W=I.shape; bg=I[0,0]
    m=(I==bg)
    lab,n=ndimage.label(m)
    # border-touching label: seed from borders, BFS over 4-connectivity of bg only
    st=[(i,j) for i in range(H) for j in (0,W-1)] + [(H-1,j) for j in range(W)] + [(i,0) for i in range(H)] + [(i,H-1) for i in range(W)] if False else []
    seen=set()
    st=[(i,j) for i in range(H) for j in (0,W-1) if m[i,j]] + [(i,0) for i in range(H) if m[i,0]] + [(0,j) for j in range(W) if m[0,j]] + [(H-1,j) for j in range(W) if m[H-1,j]]
    seen=set(st)
    while st:
        i,j=st.pop()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and (ni,nj) not in seen and m[ni,nj]:
                seen.add((ni,nj)); st.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if m[i,j] and (i,j) not in seen:
                out[i,j]=4
    return out.tolist()
